import subprocess
import sys

def run(cmd):
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    print(r.stdout[-2000:] if r.stdout else "", end="")
    if r.returncode != 0:
        print(r.stderr[-2000:], file=sys.stderr)
        sys.exit(1)
    return r.stdout

# stage everything except the two held-back session records
run("git add -A")
run("git reset -- docs/session_379.md docs/session_380.md")
staged = run("git diff --cached --stat").strip().splitlines()
